import type { NodeKindDefinition } from "@particle-academy/fancy-flow/engine";
import { gitPrChecksExecutor } from "../js/executor";

const REPO_FIELDS = [
  {
    key: "provider",
    label: "Provider",
    type: "select" as const,
    options: [
      { value: "github", label: "GitHub" },
      { value: "gitlab", label: "GitLab" },
      { value: "bitbucket", label: "Bitbucket" },
    ],
    default: "github",
  },
  { key: "owner", label: "Owner", type: "text" as const, placeholder: "Particle-Academy" },
  { key: "repo", label: "Repository", type: "text" as const, placeholder: "fancy-flow" },
];

export const GIT_PR_CHECKS_KIND = "@particle-academy/git_pr_checks";

/**
 * `git_pr_checks` — the CI gate a "merge when green" workflow routes on.
 *
 * Four ports, because `pending` is not `failing` and `none` is not `passing`.
 * Collapse them and a workflow either abandons work that was still building, or
 * merges a repository whose CI was never configured.
 */
export const gitPrChecksKind: NodeKindDefinition = {
  name: GIT_PR_CHECKS_KIND,
  aliases: ["git_pr_checks"],
  category: "logic",
  label: "Check Status",
  description: "CI state for a revision — routes on passing, failing, pending, or no checks at all.",
  icon: "✓",
  accent: "#f59e0b",
  inputs: [{ id: "in" }],
  outputs: [
    { id: "passing", label: "passing" },
    { id: "failing", label: "failing" },
    { id: "pending", label: "pending" },
    { id: "none", label: "no checks" },
  ],
  configSchema: [
    ...REPO_FIELDS,
    {
      key: "revision",
      label: "Revision",
      type: "text",
      placeholder: "a SHA or branch",
      description: "Leave empty to take it from the input — a PR's source branch will do.",
    },
  ],
  defaultConfig: { provider: "github" },
  executor: gitPrChecksExecutor,
};

import type { NodeExecutor } from "@particle-academy/fancy-flow/engine";
import { resolveTarget } from "./provider";

/**
 * CI state for a revision — the gate a "merge when green" workflow routes on.
 *
 * Four ports, because collapsing them loses the distinction that matters most:
 * `pending` is NOT `failing`. A workflow that treats "still running" as "broken"
 * either abandons good work or, worse, treats an unfinished run as a pass.
 */
export const gitPrChecksExecutor: NodeExecutor = async (ctx) => {
  const config = ((ctx.node.data as any)?.config ?? {}) as Record<string, unknown>;
  const { provider, ref } = resolveTarget(config);

  const incoming = (ctx.inputs as any)?.in;
  const revision = String(
    config.revision ?? incoming?.revision ?? incoming?.review?.sourceBranch ?? "",
  ).trim();

  if (!revision) {
    throw new Error("git_pr_checks: needs a `revision` — a SHA or branch, on the node or from its input.");
  }

  const checks = (await provider.checks(ref, revision)) ?? [];

  // No checks at all is its own answer. Reporting it as "passing" is how a
  // repository with CI misconfigured gets auto-merged.
  const failing = checks.filter((c: any) => c.state === "failed" || c.state === "failure" || c.state === "error");
  const pending = checks.filter((c: any) => c.state === "pending" || c.state === "running" || c.state === "queued");

  const port = checks.length === 0 ? "none" : failing.length > 0 ? "failing" : pending.length > 0 ? "pending" : "passing";

  ctx.emit({
    type: "log",
    level: failing.length > 0 ? "warn" : "info",
    nodeId: ctx.node.id,
    message: `${revision}: ${checks.length} check(s) — ${port}`,
  });

  return { __port: port, value: { checks, revision, failing: failing.length, pending: pending.length } };
};

/**
 * The seam between a workflow node and a hosted Git provider.
 *
 * `@particle-academy/fancy-git` models providers as a `ProviderRegistry` **instance** — it has
 * no module singleton, deliberately, because a host may serve several
 * installations with different credentials. So a node cannot reach for a
 * provider; the host has to hand one over, the same arrangement fancy-flow uses
 * for LLM clients.
 *
 * ```ts
 * import { registerGitHost } from "@/components/fancy/flow-nodes/git-pr-open/js/provider";
 * import { ProviderRegistry } from "@particle-academy/fancy-git";
 * import { githubProvider } from "@particle-academy/fancy-git-github";
 *
 * registerGitHost({
 *   registry: new ProviderRegistry().register(githubProvider({ token: env.GITHUB_TOKEN })),
 * });
 * ```
 *
 * This file is duplicated in each git-pr-* node. That is on purpose: a vendored
 * node is meant to be self-contained and editable in place, so a node you copy
 * in should not depend on another node you did not.
 */

/** What the node needs from the host, narrowed to almost nothing. */
export type GitHost = {
  /** A `ProviderRegistry` from `@particle-academy/fancy-git`. */
  registry: {
    get(kind: string): unknown;
  };
  /** Default repository, so a node's config can omit it. */
  defaultRepo?: { provider?: string; owner?: string; name?: string; baseUrl?: string };
};

let host: GitHost | null = null;

/** Install the host's provider registry. Returns an unregister function. */
export function registerGitHost(next: GitHost): () => void {
  host = next;

  return () => {
    if (host === next) host = null;
  };
}

export function getGitHost(): GitHost | null {
  return host;
}

/** A repository, as `@particle-academy/fancy-git` identifies one. */
export type RepoRef = { provider: string; owner: string; name: string; baseUrl?: string };

/**
 * Resolve the provider and repository a node should act on.
 *
 * Fails loudly at every step. A node that cannot reach a provider must not
 * return "nothing to do" — on a queue worker that is a green run that never
 * opened the pull request anyone was waiting for.
 */
export function resolveTarget(config: Record<string, unknown>): { provider: any; ref: RepoRef } {
  const current = getGitHost();
  if (!current) {
    throw new Error(
      "git_pr: no Git host registered. Call registerGitHost({ registry }) with a @particle-academy/fancy-git " +
        "ProviderRegistry — the node has no credentials of its own and must not invent any.",
    );
  }

  const ref: RepoRef = {
    provider: String(config.provider ?? current.defaultRepo?.provider ?? "github"),
    owner: String(config.owner ?? current.defaultRepo?.owner ?? ""),
    name: String(config.repo ?? current.defaultRepo?.name ?? ""),
  };
  const baseUrl = config.baseUrl ?? current.defaultRepo?.baseUrl;
  if (baseUrl) ref.baseUrl = String(baseUrl);

  if (!ref.owner || !ref.name) {
    throw new Error("git_pr: needs `owner` and `repo` — on the node, or as the host's defaultRepo.");
  }

  const provider = current.registry.get(ref.provider);
  if (!provider) {
    throw new Error(
      `git_pr: no "${ref.provider}" provider is registered. Register one on the ProviderRegistry ` +
        "you pass to registerGitHost.",
    );
  }

  return { provider, ref };
}

